import json, re, subprocess, difflib

orig = subprocess.check_output(["git","show","HEAD:modules/home-manager/agents/files/pi/herdr-subagents.json"]).decode()
old = json.loads(orig)
src = open("modules/home-manager/agents/pi.nix").read()

def nix_indented_string(block):
    lines = block.split("\n")
    if lines and lines[0] == "": lines = lines[1:]      # drop leading empty line
    indents = [len(l) - len(l.lstrip(" ")) for l in lines if l.strip()]
    common = min(indents) if indents else 0
    return "\n".join(l[common:] if l.strip() else "" for l in lines)

def extract_md_strings(text):
    result = {}
    for m in re.finditer(r'"\.pi/agent/herdr-subagents/roles/(\w+)\.md"\.text = \'\'(.*?)\'\';', text, re.S):
        result[m.group(1)] = nix_indented_string(m.group(2))
    return result

mds = extract_md_strings(src)
print("extracted roles:", sorted(mds))

def split_frontmatter(md):
    lines = md.split("\n")
    assert lines[0].strip() == "---", lines[0]
    for i in range(1, len(lines)):
        if lines[i].strip() == "---":
            return "\n".join(lines[1:i]), "\n".join(lines[i+1:])
    raise AssertionError("no closing ---")

def parse_fm(fm):
    # minimal parser for the exact shapes used here
    out = {}
    lines = fm.split("\n")
    i = 0
    while i < len(lines):
        line = lines[i]
        if not line.strip() or line.startswith(" "):  # continuation
            i += 1; continue
        key, _, rest = line.partition(":")
        key = key.strip(); rest = rest.strip()
        if rest.startswith('"') and rest.endswith('"'):
            out[key] = rest[1:-1]
        elif rest == "":
            # list follows
            items = []
            j = i + 1
            while j < len(lines) and lines[j].strip().startswith("- "):
                items.append(lines[j].strip()[2:])
                j += 1
            out[key] = items
        else:
            out[key] = rest
        i += 1
    return out

problems = []
for name in ["explore","prime","implement"]:
    md = mds[name]
    fm, body = split_frontmatter(md)
    oldrole = old["roles"][name]
    parsed = parse_fm(fm)
    for key in ["description","model","thinking"]:
        a = oldrole.get(key); b = parsed.get(key)
        if a != b:
            problems.append(f"{name}.{key}: old={a!r} new={b!r}")
        else:
            print(f"[{name}] {key}: OK ({a!r})")
    a = oldrole["prompt"]; b = body.strip()
    if a == b:
        print(f"[{name}] prompt: IDENTICAL")
    else:
        problems.append(f"{name}.prompt differs")
        d = list(difflib.unified_diff(a.split("\n"), b.split("\n"), "old-json", "new-md", lineterm=""))
        print(f"[{name}] prompt DIFFERS:\n" + "\n".join(d[:80]))
print("\n=== PROBLEMS ===" if problems else "\n=== NO PROBLEMS: metadata+prompts all identical ===")
for p in problems: print(" -", p)
PYEOF

